class AutocompleteSystem {
  private count = new Map<string, number>();
  private typed = "";

  constructor(sentences: string[], times: number[]) {
    sentences.forEach((s, i) => this.count.set(s, times[i]));
  }

  input(c: string): string[] {
    if (c === "#") {
      this.count.set(this.typed, (this.count.get(this.typed) ?? 0) + 1);
      this.typed = "";
      return [];
    }
    this.typed += c;
    return [...this.count]
      .filter(([s]) => s.startsWith(this.typed))
      .sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
      .slice(0, 3)
      .map(([s]) => s);
  }
}

