class TrieNode {
  kids = new Map<string, TrieNode>();
  hits = new Map<string, number>();
}

class AutocompleteSystem {
  private root = new TrieNode();
  private cur: TrieNode | null = this.root;
  private typed = "";

  constructor(sentences: string[], times: number[]) {
    sentences.forEach((s, i) => this.add(s, times[i]));
  }

  private add(s: string, k: number): void {
    let node = this.root;
    for (const ch of s) {
      if (!node.kids.has(ch)) node.kids.set(ch, new TrieNode());
      node = node.kids.get(ch)!;
      node.hits.set(s, (node.hits.get(s) ?? 0) + k);
    }
  }

  input(c: string): string[] {
    if (c === "#") {
      this.add(this.typed, 1);
      this.typed = "";
      this.cur = this.root;
      return [];
    }
    this.typed += c;
    this.cur = this.cur ? this.cur.kids.get(c) ?? null : null;
    if (!this.cur) return [];
    return [...this.cur.hits]
      .sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
      .slice(0, 3)
      .map(([s]) => s);
  }
}

